+Set-StrictMode -Version Latest
+$ErrorActionPreference = 'Stop'
+
+function Get-RunnerDeploymentConfig {
+    [CmdletBinding()]
+    param([Parameter(Mandatory = $true)][string]$Path)
+
+    $resolved = (Resolve-Path -LiteralPath $Path).ProviderPath
+    $config = Get-Content -LiteralPath $resolved -Raw -Encoding UTF8 | ConvertFrom-Json
+    if ($config.schema_version -ne 'windows_hyperv_runner_deployment_v1') {
+        throw "Unsupported deployment config schema: $($config.schema_version)"
+    }
+    return $config
+}
+
+function Test-RunnerAdministrator {
+    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
+    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
+    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
+}
+
+function Assert-RunnerAdministrator {
+    if (-not (Test-RunnerAdministrator)) {
+        throw 'This stage requires an elevated Windows PowerShell session.'
+    }
+}
+
+function Assert-RunnerWindowsHost {
+    if ($env:OS -ne 'Windows_NT') {
+        throw 'This script must run on the target Windows host, not inside WSL or a guest.'
+    }
+}
+
+function Assert-RunnerStorageAligned {
+    param([Parameter(Mandatory = $true)]$Config)
+
+    if ($Config.storage.alignment_status -ne 'confirmed_on_target') {
+        throw 'Storage is unresolved. Run stage 00, obtain owner confirmation, then set alignment_status=confirmed_on_target and fill pool_vhdx_path, pool_drive_letter and pool_size_gib.'
+    }
+    if ([string]::IsNullOrWhiteSpace([string]$Config.storage.pool_vhdx_path)) {
+        throw 'storage.pool_vhdx_path is required.'
+    }
+    if ([string]::IsNullOrWhiteSpace([string]$Config.storage.pool_drive_letter)) {
+        throw 'storage.pool_drive_letter is required.'
+    }
+    if ($null -eq $Config.storage.pool_size_gib -or [int]$Config.storage.pool_size_gib -lt [int]$Config.storage.minimum_pool_size_gib) {
+        throw 'storage.pool_size_gib is missing or below minimum_pool_size_gib.'
+    }
+}
+
+function Get-RunnerDeploymentStateRoot {
+    return Join-Path $env:ProgramData 'CIECopilotRunner\deployment'
+}
+
+function Write-RunnerStageReceipt {
+    [CmdletBinding()]
+    param(
+        [Parameter(Mandatory = $true)][string]$Stage,
+        [Parameter(Mandatory = $true)][ValidateSet('pass', 'fail', 'pending', 'changed')][string]$Status,
+        [Parameter(Mandatory = $true)]$Details,
+        [string]$OutputPath
+    )
+
+    if ([string]::IsNullOrWhiteSpace($OutputPath)) {
+        $receiptDirectory = Join-Path (Get-RunnerDeploymentStateRoot) 'receipts'
+        New-Item -ItemType Directory -Path $receiptDirectory -Force | Out-Null
+        $OutputPath = Join-Path $receiptDirectory "$Stage.json"
+    } else {
+        $parent = Split-Path -Parent $OutputPath
+        if ($parent) {
+            New-Item -ItemType Directory -Path $parent -Force | Out-Null
+        }
+    }
+
+    $receipt = [ordered]@{
+        schema_version = 'windows_hyperv_runner_stage_receipt_v1'
+        stage = $Stage
+        status = $Status
+        generated_at = [DateTime]::UtcNow.ToString('o')
+        computer_name = $env:COMPUTERNAME
+        user_name = [Security.Principal.WindowsIdentity]::GetCurrent().Name
+        details = $Details
+    }

